<?php
require '/scratch/site/wp-load.php';
wp_set_current_user(1);
$pages=[];foreach(['dashboard'=>'[tutor_dashboard]','cart'=>'[tutor_cart]','checkout'=>'[tutor_checkout]','courses'=>'','terms'=>'Synthetic terms','privacy-policy'=>'Synthetic privacy'] as $slug=>$content){$pages[$slug]=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_name'=>$slug,'post_title'=>ucwords(str_replace('-',' ',$slug)),'post_content'=>$content]);}
$options=get_option('tutor_option',[]);$options=array_merge($options,['monetize_by'=>'tutor','currency_code'=>'GBP','tutor_dashboard_page_id'=>$pages['dashboard'],'course_archive_page'=>$pages['courses'],'tutor_toc_page_id'=>$pages['terms'],'enable_tutor_native_login'=>true,'ecommerce_checkout_enable_guest_checkout'=>false]);update_option('tutor_option',$options);update_option('tutor_dashboard_page_id',$pages['dashboard']);update_option('tutor_cart_page_id',$pages['cart']);update_option('tutor_checkout_page_id',$pages['checkout']);update_option('wp_page_for_privacy_policy',$pages['privacy-policy']);update_option('permalink_structure','/%postname%/');flush_rewrite_rules(false);
$users=[];foreach(['floweditor'=>'cas_content','flowother'=>'cas_content','flowstudent'=>'subscriber','flowoutsider'=>'subscriber'] as $login=>$role){$id=wp_create_user($login,'Synthetic-Only-Flow-2026',$login.'@example.test');if(is_wp_error($id))throw new Exception($id->get_error_message());(new WP_User($id))->set_role($role);if('cas_content'===$role){update_user_meta($id,'_is_tutor_instructor',tutor_time());update_user_meta($id,'_tutor_instructor_status','approved');}$users[$login]=$id;}
file_put_contents('/scratch/config.json',json_encode(compact('users','pages')));echo json_encode(['users'=>$users,'pages'=>$pages,'attachments_enabled'=>tutor_utils()->is_addon_enabled('tutor-course-attachments')]);
